// ── Union-Find (Disjoint Set Union) ───────────────────────────
class UnionFind {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i); // each node is its own root
    this.rank   = new Array(n).fill(0);                   // tree height upper bound
  }

  find(x) {
    if (this.parent[x] !== x)
      this.parent[x] = this.find(this.parent[x]); // path compression
    return this.parent[x];
  }

  union(x, y) {
    const px = this.find(x), py = this.find(y);
    if (px === py) return false; // same component — adding edge would create cycle
    // union by rank: attach shorter tree under taller
    if      (this.rank[px] < this.rank[py]) this.parent[px] = py;
    else if (this.rank[px] > this.rank[py]) this.parent[py] = px;
    else { this.parent[py] = px; this.rank[px]++; } // equal rank: pick one, increment
    return true;
  }
}

// ── Kruskal's Algorithm — O(E log E) ──────────────────────────
// edges: array of [u, v, weight]  (vertices 0-indexed)
function kruskal(numVertices, edges) {
  edges.sort((a, b) => a[2] - b[2]); // sort ascending by weight
  const uf = new UnionFind(numVertices);
  const mstEdges = [];
  let totalWeight = 0;

  for (const [u, v, w] of edges) {
    if (uf.union(u, v)) {           // returns true if they were in different components
      mstEdges.push([u, v, w]);
      totalWeight += w;
      if (mstEdges.length === numVertices - 1) break; // MST complete — stop early
    }
  }
  return { mstEdges, totalWeight };
}

// Graph: A=0, B=1, C=2, D=3
// Edges sorted by weight: A-B(1), B-C(2), A-C(3), B-D(4), C-D(5)
const edges = [
  [0, 1, 1], // A-B weight 1
  [0, 2, 3], // A-C weight 3
  [1, 2, 2], // B-C weight 2
  [1, 3, 4], // B-D weight 4
  [2, 3, 5], // C-D weight 5
];

const { mstEdges, totalWeight } = kruskal(4, edges);
console.log(mstEdges);    // [[0,1,1], [1,2,2], [1,3,4]]
console.log(totalWeight); // 7

// Step-by-step trace:
// A-B(1): find(A)=A, find(B)=B → different → union, add. Components: {A,B},{C},{D}
// B-C(2): find(B)=A, find(C)=C → different → union, add. Components: {A,B,C},{D}
// A-C(3): find(A)=A, find(C)=A → SAME → skip (would create cycle A-B-C-A)
// B-D(4): find(B)=A, find(D)=D → different → union, add. Components: {A,B,C,D}
// MST complete: 3 edges = V-1, total weight = 7

// ── Prim's Algorithm — O((V+E) log V) with binary min-heap ───
// graph: Map or object { node: [[neighbor, weight], ...] }
// Uses lazy deletion: skip stale heap entries
function prim(graph, startNode) {
  const inMST   = new Set();
  const mstEdges = [];
  let totalWeight = 0;

  // Min-heap entries: [weight, fromNode, toNode]
  // We simulate a min-heap with a sorted array here for clarity
  // (in production use a proper priority queue)
  const heap = [];

  function heapPush(entry) {
    heap.push(entry);
    heap.sort((a, b) => a[0] - b[0]); // sort by weight
  }
  function heapPop() {
    return heap.shift(); // remove minimum
  }

  // Seed: add startNode and enqueue its edges
  inMST.add(startNode);
  for (const [neighbor, w] of (graph[startNode] || [])) {
    heapPush([w, startNode, neighbor]);
  }

  while (heap.length > 0 && mstEdges.length < Object.keys(graph).length - 1) {
    const [w, u, v] = heapPop();

    if (inMST.has(v)) continue; // stale entry — v already added via a cheaper edge

    // v is a new vertex — add it to the MST
    inMST.add(v);
    mstEdges.push([u, v, w]);
    totalWeight += w;

    // Enqueue all edges from v to non-MST vertices
    for (const [neighbor, weight] of (graph[v] || [])) {
      if (!inMST.has(neighbor)) {
        heapPush([weight, v, neighbor]);
      }
    }
  }

  return { mstEdges, totalWeight };
}

const graph = {
  A: [["B", 1], ["C", 3]],
  B: [["A", 1], ["C", 2], ["D", 4]],
  C: [["A", 3], ["B", 2], ["D", 5]],
  D: [["B", 4], ["C", 5]]
};

const result = prim(graph, "A");
console.log(result.mstEdges);    // [["A","B",1], ["B","C",2], ["B","D",4]]
console.log(result.totalWeight); // 7

